// HasEdgeoneZone applies the HasEdge predicate on the "edgeone_zone" edge.
func HasEdgeoneZone() predicate.EdgeOneZoneDNSRecord {
	return predicate.EdgeOneZoneDNSRecord(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, EdgeoneZoneTable, EdgeoneZoneColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasEdgeoneZoneWith applies the HasEdge predicate on the "edgeone_zone" edge with a given conditions (other predicates).
func HasEdgeoneZoneWith(preds ...predicate.EdgeOneZone) predicate.EdgeOneZoneDNSRecord {
	return predicate.EdgeOneZoneDNSRecord(func(s *sql.Selector) {
		step := newEdgeoneZoneStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

